+  font-family: Lato,sans-serif !important;
+  color: #333333 !important;
+}
+body .recombinant-dictionary[data-published-resource="True"] .panel-heading > .panel-title:not(.collapsed){
+  background-color: #e9f0f3 !important;
+}
+body .recombinant-dictionary[data-published-resource="True"] .panel-heading > .panel-title:not(.collapsed) *{
+  color: #1d6075 !important;
+}
+body .recombinant-dictionary[data-published-resource="True"] .panel-heading .recombinant-dictionary-item-expand{
+  font-size: 24px !important;
+  line-height: 1 !important;
+  width: 12px;
+  height: 12px;
+  display: block;
+  transition-duration: 0.125s;
+  transform-origin: center;
+  transform: translateX(-50%) translateY(-50%) rotate(90deg);
+  position: absolute;
+  top: 50%;
+  left: 50%;
+}
+body .recombinant-dictionary[data-published-resource="True"] .panel-heading > .panel-title:not(.collapsed) .recombinant-dictionary-item-expand{
+  transform: translateX(-200%) translateY(-50%) rotate(-90deg);
+}

